-- Brand kit part 4, the Guide roster, locked by Sean 2026-11-11 ("Lock it, go with your defaults"). Each step is safe to run twice.

-- step: roster
update public.ve_character_roster set guide_title='The Travel Guide', path_label='Travel', path_number=3, updated_at=now() where slug='nori';
update public.ve_character_roster set guide_title='The Causes Guide', path_label='Causes', path_number=4, updated_at=now() where slug='dani';
update public.ve_character_roster set guide_title='The Going Out Guide', path_label='Going Out', path_number=8, updated_at=now() where slug='river';
update public.ve_character_roster set guide_title='The Food Guide', path_label='Food', path_number=7, updated_at=now() where slug='pascal';
insert into public.ve_character_roster (slug,name,guide_title,path_number,path_label,visual_description,reference_url,art_style,locked) select 'kai','Kai Monroe','Creator Guide',5,'Creator','Teal curls with a shaved side, round tortoiseshell glasses, a mustard overshirt over a white tee. Walks the Creator Guide, the Creator Dashboard and the Nominate Someone interview.','https://vegansexplore.com/gigs/sample/img/kai-avatar.webp','Vegans Explore illustration style',true where not exists (select 1 from public.ve_character_roster where slug='kai');

-- step: bios
update public.gfs_artist_bible set data = data || jsonb_build_object('bio','Liz is the main face of Vegans Explore and the bridge between people and the businesses they are looking for. Whatever you need, Vegan or just curious, she helps you find it and tells the stories of the people behind it.','guide_title','The Explorer','walks','Welcome Guide, Vegan Restaurant Guide, Pre-Vegan Restaurant Guide, Businesses, across every Guide'), version = version + 1, updated_by='logan', updated_at=now() where artist_slug='liz' and module='lore' and coalesce(data->>'bio','') <> 'Liz is the main face of Vegans Explore and the bridge between people and the businesses they are looking for. Whatever you need, Vegan or just curious, she helps you find it and tells the stories of the people behind it.';
update public.gfs_artist_bible set data = data || jsonb_build_object('bio','Maya is for everyone who hears about Vegans Explore and is not Vegan yet, which is most people. She makes every first step easy, from a dairy swap to a menu with plant-based (Pre-Vegan) options.','guide_title','Pre-Vegan Guide','walks','Vegan Dairy Guide, Pre-Vegan Business Guide'), version = version + 1, updated_by='logan', updated_at=now() where artist_slug='maya' and module='lore' and coalesce(data->>'bio','') <> 'Maya is for everyone who hears about Vegans Explore and is not Vegan yet, which is most people. She makes every first step easy, from a dairy swap to a menu with plant-based (Pre-Vegan) options.';
update public.gfs_artist_bible set data = data || jsonb_build_object('bio','Theo has been around the block: he knows the lay of the land and where to find everything, and he shares it with the patience of someone who has seen it all. The holidays are his.','guide_title','Seasoned Vegan Guide','walks','Holiday Guide, Nutrition Guide'), version = version + 1, updated_by='logan', updated_at=now() where artist_slug='theo' and module='lore' and coalesce(data->>'bio','') <> 'Theo has been around the block: he knows the lay of the land and where to find everything, and he shares it with the patience of someone who has seen it all. The holidays are his.';
update public.gfs_artist_bible set data = data || jsonb_build_object('bio','Nori is our world traveler: wherever you are headed, he knows where to eat between the gates and once you land. As travel and tourism grow on Vegans Explore, he leads it.','guide_title','The Travel Guide','walks','Airport Guide, Travel, as it grows'), version = version + 1, updated_by='logan', updated_at=now() where artist_slug='nori' and module='lore' and coalesce(data->>'bio','') <> 'Nori is our world traveler: wherever you are headed, he knows where to eat between the gates and once you land. As travel and tourism grow on Vegans Explore, he leads it.';
update public.gfs_artist_bible set data = data || jsonb_build_object('bio','Dani is here for the animals and the community causes that protect them. She introduces you to every rescue, sanctuary and nonprofit near you, and shows you how to help.','guide_title','The Causes Guide','walks','Nonprofit Guide'), version = version + 1, updated_by='logan', updated_at=now() where artist_slug='dani' and module='lore' and coalesce(data->>'bio','') <> 'Dani is here for the animals and the community causes that protect them. She introduces you to every rescue, sanctuary and nonprofit near you, and shows you how to help.';
update public.gfs_artist_bible set data = data || jsonb_build_object('bio','River is from Atlanta, quick on his feet and always three steps ahead of where the best plant-based plate is: at the game, the park or the pop-up.','guide_title','The Going Out Guide','walks','Vegan Events Guide, Stadium & Arena Guide, Theme Park Guide'), version = version + 1, updated_by='logan', updated_at=now() where artist_slug='river' and module='lore' and coalesce(data->>'bio','') <> 'River is from Atlanta, quick on his feet and always three steps ahead of where the best plant-based plate is: at the game, the park or the pop-up.';
update public.gfs_artist_bible set data = data || jsonb_build_object('bio','Pascal is a chef, and food is his whole world: recipes, cooking and, soon, our cookbooks. He takes you from the grocery aisle to a plate worth sharing.','guide_title','The Food Guide','walks','Supermarket Guide, Recipes and cookbooks, coming'), version = version + 1, updated_by='logan', updated_at=now() where artist_slug='pascal' and module='lore' and coalesce(data->>'bio','') <> 'Pascal is a chef, and food is his whole world: recipes, cooking and, soon, our cookbooks. He takes you from the grocery aisle to a plate worth sharing.';
insert into public.gfs_artist_bible (artist_slug,module,module_label,data,version,status,updated_by) select 'kai','lore','Lore',jsonb_build_object('bio','Kai is a Miami creator who shows other creators how to grow with Vegans Explore, and runs the interview when someone gets nominated.','brand','Vegans Explore','guide_title','Creator Guide','walks','Creator Guide, Creator Dashboard, Nominate Someone'),1,'draft','logan' where not exists (select 1 from public.gfs_artist_bible where artist_slug='kai' and module='lore');

-- step: canon
insert into public.knowledge_records (slug,title,category,subcategory,body,status,owner,always_load,load_priority,tags,version,change_summary,created_by,updated_by) select 'canon-ve-guide-roster','Vegans Explore Guide roster (LOCKED)','brand','canonical',$j${"authority": "Sean, 2026-11-11: \"Lock it, go with your defaults\" after his roster notes.", "reference": "/mocks/brand-kit/roster", "home": "Sean: \"once we figure out the dashboard situation in the back end, I want this to live inside of the brand desk.\"", "roster": {"liz": {"name": "Liz", "title": "The Explorer", "bio": "Liz is the main face of Vegans Explore and the bridge between people and the businesses they are looking for. Whatever you need, Vegan or just curious, she helps you find it and tells the stories of the people behind it.", "walks": ["Welcome Guide", "Vegan Restaurant Guide", "Pre-Vegan Restaurant Guide", "Businesses, across every Guide"], "voice_id": "IUMUPi350HfIhyzUBJB3", "look": "Auburn hair in a loose low ponytail, warm brown eyes, freckles; the pink Vegans Explore tee is her favorite."}, "maya": {"name": "Maya", "title": "Pre-Vegan Guide", "bio": "Maya is for everyone who hears about Vegans Explore and is not Vegan yet, which is most people. She makes every first step easy, from a dairy swap to a menu with plant-based (Pre-Vegan) options.", "walks": ["Vegan Dairy Guide", "Pre-Vegan Business Guide"], "voice_id": "sM8RysETdBj1LIqLd9tl", "look": "Voluminous curly dark hair, warm brown skin, denim jacket over a white tee, a recipe booklet in hand."}, "theo": {"name": "Theo", "title": "Seasoned Vegan Guide", "bio": "Theo has been around the block: he knows the lay of the land and where to find everything, and he shares it with the patience of someone who has seen it all. The holidays are his.", "walks": ["Holiday Guide", "Nutrition Guide"], "voice_id": "aFyw0oiXW7dzKF4o7woX", "look": "Salt-and-pepper hair and full beard, wire-frame glasses, a calm, distinguished presence."}, "nori": {"name": "Nori", "title": "The Travel Guide", "bio": "Nori is our world traveler: wherever you are headed, he knows where to eat between the gates and once you land. As travel and tourism grow on Vegans Explore, he leads it.", "walks": ["Airport Guide", "Travel, as it grows"], "voice_id": "rr9oBze1kuNJYeAV7xos", "look": "Short dark straight hair, his notebook always with him; drawn ready to travel from the next scene on."}, "dani": {"name": "Dani", "title": "The Causes Guide", "bio": "Dani is here for the animals and the community causes that protect them. She introduces you to every rescue, sanctuary and nonprofit near you, and shows you how to help.", "walks": ["Nonprofit Guide"], "voice_id": "b5RPB35vTODb3BEmR3Fc", "look": "Long curly dark brown hair, colorful hoop earrings, always drawn seated in her manual wheelchair."}, "river": {"name": "River", "title": "The Going Out Guide", "bio": "River is from Atlanta, quick on his feet and always three steps ahead of where the best plant-based plate is: at the game, the park or the pop-up.", "walks": ["Vegan Events Guide", "Stadium & Arena Guide", "Theme Park Guide"], "voice_id": "btaSeNTVh1pGx4pjFzub", "look": "In his 20s, short black twists with a fade, warm brown skin, an easy smile."}, "kai": {"name": "Kai Monroe", "title": "Creator Guide", "bio": "Kai is a Miami creator who shows other creators how to grow with Vegans Explore, and runs the interview when someone gets nominated.", "walks": ["Creator Guide", "Creator Dashboard", "Nominate Someone"], "voice_id": "cgSgspJ2msm6clMCkdW9", "look": "Teal curls with a shaved side, round tortoiseshell glasses, a mustard overshirt; the next drawing adds the Vegans Explore mark."}, "pascal": {"name": "Pascal", "title": "The Food Guide", "bio": "Pascal is a chef, and food is his whole world: recipes, cooking and, soon, our cookbooks. He takes you from the grocery aisle to a plate worth sharing.", "walks": ["Supermarket Guide", "Recipes and cookbooks, coming"], "voice_id": null, "look": "The chef of the roster; his next drawing puts him in an apron with the Vegans Explore mark."}}, "roles": "Liz is the main face and the bridge to businesses (\"business is a part of every single thing, so it's hard to just have one person over all businesses\"); Maya is for everyone not Vegan yet; Theo has been around the block; Nori is the Travel Guide (\"no longer the entrepreneurial guide\"); Dani is the Causes Guide (Sean's default accepted; she walks the Nonprofit Guide); River is the Going Out Guide, events and venues; Kai is the Creator Guide; Pascal is the Food Guide, a chef (recipes and cookbooks coming).", "open": ["Pascal has no voice: bring Sean three chef voices to pick from (never pick one without him)", "LESARUSS-style profile avatars after the Higgsfield top-up, in this order: Liz, Theo, Maya, River, Kai, Dani, Nori, Pascal; Kai's and Pascal's next drawings carry the Vegans Explore mark", "The member path system (Entrepreneur path) no longer has its own Guide since Nori became the Travel Guide; Liz bridges business; review where the path picker names a Guide before changing it"]}$j$::jsonb,'active','sar',false,20,array['vegans-explore','brand','brand-kit','guides','roster','canon'],1,'Created: Sean locked the Guide roster with his notes and the defaults.','logan','logan' where not exists (select 1 from public.knowledge_records where slug='canon-ve-guide-roster');
